#!/usr/bin/env python3
"""One-click retention of the actual temporary Arb backend used by v0.9.30.

This is the correct source-export step before repository-native callbacks are
refactored. It does not claim point/box X, DX, a QR/Lohner flowpipe, or a fifth
frame.
"""
from __future__ import annotations
import argparse, base64, gzip, hashlib, json, os, subprocess, sys, tempfile
from pathlib import Path

TITLE="GEOMETRIC-FLOW ACTIVE ARB BACKEND SOURCE RETENTION"
VERSION="0.10.1"
V0930_GZIP_B64=""

def sha(p):
 h=hashlib.sha256()
 with Path(p).open("rb") as f:
  for b in iter(lambda:f.read(1<<20),b""):h.update(b)
 return h.hexdigest()

def clean_args(argv):
 out=[];ignored=[];i=0
 while i<len(argv):
  if argv[i]=="-f" and i+1<len(argv):ignored+=argv[i:i+2];i+=2
  else:out.append(argv[i]);i+=1
 if ignored:print(f"[notice] ignored notebook/kernel arguments: {ignored}")
 return out

def main():
 ap=argparse.ArgumentParser()
 ap.add_argument("--outdir",default="geometric_flow_native_source_v0_10_1_results")
 args,_=ap.parse_known_args(clean_args(sys.argv[1:]))
 out=Path(args.outdir).resolve();out.mkdir(parents=True,exist_ok=True)
 source=gzip.decompress(base64.b64decode(V0930_GZIP_B64)).decode()
 hook=' text=drivers[0].read_text()\n'
 if source.count(hook)!=1:raise RuntimeError("v0.9.30 driver-text hook not unique")
 driver_old=' patched=out/"instrumented_v0_9_3_generator_for_v0_9_8.py";patched.write_text(patch_generator(v093.read_text()))'
 generator_needle='        patched.write_text(\n            patch_frozen_source(source_path.read_bytes()), encoding="utf-8"\n        )'
 generator_retain=generator_needle+'\n        Path(os.environ["V0101_EXPORT_ACTIVE_BACKEND"]).write_text(\n            patched.read_text(encoding="utf-8"), encoding="utf-8"\n        )'
 driver_new=(
  ' _generated=patch_generator(v093.read_text())\n'
  ' _needle='+repr(generator_needle)+'\n'
  ' _retain='+repr(generator_retain)+'\n'
  ' if _generated.count(_needle)<1:raise RuntimeError("v0.10.1 temporary Arb source hook absent")\n'
  ' _pos=_generated.rfind(_needle)\n'
  ' _generated=_generated[:_pos]+_retain+_generated[_pos+len(_needle):]\n'
  ' patched=out/"instrumented_v0_9_3_generator_for_v0_9_8.py"\n'
  ' patched.write_text(_generated)'
 )
 injection=(hook+
  ' if text.count('+repr(driver_old)+')!=1:raise RuntimeError("v0.10.1 v0.9.8 generator hook not unique")\n'+
  ' text=text.replace('+repr(driver_old)+','+repr(driver_new)+',1)\n')
 source=source.replace(hook,injection,1)
 patched=out/"instrumented_v0_9_30_source_retention.py";patched.write_text(source)
 active=out/"active_repository_native_arb_backend_v0_9_30.py"
 env=dict(os.environ);env["V0101_EXPORT_ACTIVE_BACKEND"]=str(active)
 dep=Path("/tmp/geometric_flow_v0100_flint")
 if dep.is_dir():env["PYTHONPATH"]=str(dep)+os.pathsep+env.get("PYTHONPATH","")
 runout=out/"v0930_reproduction"
 done=subprocess.run([sys.executable,str(patched),"--outdir",str(runout)],
  text=True,capture_output=True,env=env)
 (out/"stdout.txt").write_text(done.stdout);(out/"stderr.txt").write_text(done.stderr)
 markers={}
 if active.is_file():
  text=active.read_text()
  for name in ["response_jacobian_and_gradient","projective_jet_and_derivatives",
               "phase_and_derivative_at"]:
   markers[name]=("def "+name+"(") in text
 status="ACTIVE_REPOSITORY_NATIVE_ARB_SOURCE_RETAINED" if done.returncode==0 and active.is_file() and all(markers.values()) else "V0101_FAILED_CLOSED"
 report={"title":TITLE,"version":VERSION,"scientific_status":status,
  "v0930_exit_zero":done.returncode==0,"active_backend":str(active) if active.is_file() else None,
  "active_backend_sha256":sha(active) if active.is_file() else None,
  "active_backend_size":active.stat().st_size if active.is_file() else None,
  "formula_entry_points":markers,
  "all_scientific_gates_pass":False,
  "repository_native_primitives_ready":False,
  "next_required_step":"extract dependency-closed public response_map, response_jacobian_and_gradient, and L6 gradient callbacks from the retained source",
  "claim_boundary":"source retention only; no point/box field, same-expression DX, QR/Lohner flowpipe, fifth frame, or global flow"}
 (out/"run_summary.json").write_text(json.dumps(report,indent=2)+"\n")
 print("="*112);print(f"{TITLE} v{VERSION}");print("="*112);print(json.dumps(report,indent=2))
 return 0 if status.startswith("ACTIVE_") else 2

if __name__=="__main__":
 code=main()
 if "ipykernel" not in sys.modules and "IPython" not in sys.modules and "google.colab" not in sys.modules:
  raise SystemExit(code)
